function App() {
  const [count, setCount] = useState(0);
  return (
    <div className="box">
      <h2>Count: {count}</h2>
      <button onClick={() => setCount(count + 1)}>+1</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  );
}

function A() { return <input placeholder="I am A - type here" />; }
function B() { return <textarea placeholder="I am B - type here" />; }

function App() {
  const [useA, setUseA] = useState(true);
  return (
    <div>
      <button onClick={() => setUseA(!useA)}>Switch</button>
      <div style={{ marginTop: 10 }}>{useA ? <A /> : <B />}</div>
    </div>
  );
}

function App() {
  const user = { name: "Asha", age: 24 };
  const isAdult = user.age >= 18;
  return (
    <>
      {/* This is a JSX comment */}
      <h2 className="title" style={{ color: "teal", fontSize: 22 }}>
        Hello, {user.name.toUpperCase()}!
      </h2>
      <p>Next year you will be {user.age + 1}.</p>
      <p>{isAdult ? "Adult" : "Minor"}</p>
      <label htmlFor="n">Name: </label>
      <input id="n" defaultValue={user.name} />
      <br />
    </>
  );
}

function Card({ title, price, inStock = true, onBuy }) {
  return (
    <div className="card">
      <h3>{title}</h3>
      <p>Price: Rs. {price}</p>
      <p>{inStock ? "In stock" : "Sold out"}</p>
      <button disabled={!inStock} onClick={() => onBuy(title)}>Buy</button>
    </div>
  );
}

function App() {
  const [msg, setMsg] = useState("Nothing bought yet");
  return (
    <div>
      <p><b>{msg}</b></p>
      <Card title="Keyboard" price={1999} onBuy={(t) => setMsg("Bought " + t)} />
      <Card title="Mouse" price={799} inStock={false} onBuy={(t) => setMsg("Bought " + t)} />
    </div>
  );
}

topics.description:
Whatever you put between `<Card>` and `</Card>` is passed to the component as the special prop **`children`**. This lets you build generic wrapper components (layouts, panels, modals, buttons) that do not know their content in advance.

```jsx
function Panel({ title, children }) {
  return (
    <section>
      <h3>{title}</h3>
      {children}
    </section>
  );
}
```

### What can children be?

Text, a single element, an array of elements, a function (render prop), or nothing (`undefined`). Because the type varies, avoid assuming it is an array.

### Children utilities

`React.Children` has `map`, `count`, `toArray` and `only` helpers. They are useful but fragile, because they only see direct children and break when someone wraps them in a Fragment or another component. Prefer **composition** and explicit props (slots) for complex cases.

### Multiple slots

If you need several areas, pass JSX as normal props: `<Layout header={<Nav />} sidebar={<Menu />}>...</Layout>`.

### Why it matters

`children` is the base of composition in React: instead of configuring a component with many flags, you hand it the content you want inside.

examples.code:
function Panel({ title, footer, children }) {
  return (
    <section className="panel">
      <h3>{title}</h3>
      <div>{children}</div>
      {footer && <small>{footer}</small>}
    </section>
  );
}

function App() {
  return (
    <Panel title="Profile" footer="Last updated today">
      <p>Name: Asha</p>
      <p>Role: Developer</p>
    </Panel>
  );
}

function Status({ loading, error }) {
  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: "crimson" }}>Error: {error}</p>;
  return <p>All good</p>;
}

function App() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [items] = useState([]);
  return (
    <div>
      <button onClick={() => setLoggedIn(!loggedIn)}>
        {loggedIn ? "Log out" : "Log in"}
      </button>
      {loggedIn && <p>Welcome back!</p>}
      {items.length > 0 && <ul><li>never shown</li></ul>}
      <Status loading={false} error={loggedIn ? null : "Please log in"} />
    </div>
  );
}

function Row({ name }) {
  return (
    <li>
      {name}: <input placeholder="note" />
    </li>
  );
}

function App() {
  const [people, setPeople] = useState([
    { id: 1, name: "Asha" },
    { id: 2, name: "Ravi" },
    { id: 3, name: "Meera" },
  ]);
  return (
    <div>
      <button onClick={() => setPeople([...people].reverse())}>Reverse</button>
      <ul>
        {people.map((p) => (
          <Row key={p.id} name={p.name} />
        ))}
      </ul>
    </div>
  );
}

function App() {
  const [text, setText] = useState("");
  const [log, setLog] = useState([]);

  function handleSubmit(e) {
    e.preventDefault();
    if (!text.trim()) return;
    setLog([...log, text]);
    setText("");
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => e.key === "Escape" && setText("")}
          placeholder="Type, Enter to add, Esc clears"
        />
        <button type="submit">Add</button>
      </form>
      <ul>{log.map((l, i) => <li key={i}>{l}</li>)}</ul>
    </div>
  );
}

function SearchBar({ value, onChange }) {
  return <input placeholder="Search..." value={value} onChange={(e) => onChange(e.target.value)} />;
}
function ProductRow({ product }) {
  return <li>{product.name} - Rs. {product.price}</li>;
}
function ProductList({ products }) {
  if (products.length === 0) return <p>No products</p>;
  return <ul>{products.map((p) => <ProductRow key={p.id} product={p} />)}</ul>;
}

const DATA = [
  { id: 1, name: "Apple", price: 120 },
  { id: 2, name: "Banana", price: 40 },
  { id: 3, name: "Mango", price: 90 },
];

function App() {
  const [query, setQuery] = useState("");
  const visible = DATA.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
  return (
    <div>
      <SearchBar value={query} onChange={setQuery} />
      <ProductList products={visible} />
    </div>
  );
}
